});

Deno.test("eating 3 rat corpses grants iron_stomach trait", () => {
  const world = new World({ seed: 0xFEED02 });
  const player = createPlayer(world, { x: 0, y: 0, name: "Hero" });

  const traitEvents = [];
  world.on("corpse:trait-gained", (ev) => traitEvents.push(ev));

  for (let i = 0; i < 3; i++) {
