      source: "itemHooks",
      beforeUse: hooks.beforeUse,
      onUse: hooks.onUse,
      afterUse: hooks.afterUse,
    };
  }

  for (let i = 0; i < USE_ITEM_MATCHER_PAYLOADS.length; i++) {
